export function elapsedSeconds(delivery,at=Date.now()){const start=Date.parse(delivery.enteredAt),end=Date.parse(delivery.readyAt||delivery.departedAt||delivery.completedAt);return Number.isFinite(start)?Math.max(0,Math.floor(((Number.isFinite(end)?end:at)-start)/1000)):0;}
export function elapsedLabel(seconds){return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;}
export function delayDue(delivery,at=Date.now()){return ['pending','ready'].includes(delivery.status)&&!delivery.departedAt&&!delivery.preparationDelayReviewedAt&&Number.isFinite(Date.parse(delivery.enteredAt))&&at-Date.parse(delivery.enteredAt)>=20*60000;}
export const DELAY_MESSAGE='Your order from Srivilai Thai Cuisine is taking a little longer to prepare than expected. We’ll be on our way as soon as it’s ready. Thank you for your patience!';
export function calculateTips(entries,serverCount){if(!Number.isInteger(serverCount)||serverCount<1||serverCount>100)throw Error('Enter a whole number of servers from 1 to 100.');const tickets=entries.filter(x=>String(x.amount).trim()!=='').map(x=>{const text=String(x.amount).trim();if(!/^\d+(?:\.\d{1,2})?$/.test(text))throw Error('Enter each tip as a positive amount with up to two decimal places.');const cents=Math.round(Number(text)*100);if(!Number.isSafeInteger(cents)||cents>100000000)throw Error('Tip amount is too large.');return {ticket:String(x.ticket||'').trim().slice(0,80),cents};});if(!tickets.length)throw Error('Enter at least one ticket tip (0 is allowed).');const totalCents=tickets.reduce((n,x)=>n+x.cents,0);if(!Number.isSafeInteger(totalCents)||totalCents>100000000)throw Error('Total tips are too large.');const kitchenCents=Math.round(totalCents*.15),serversCents=Math.round(totalCents*.15),driverCents=totalCents-kitchenCents-serversCents,each=Math.floor(serversCents/serverCount),extra=serversCents%serverCount;return {tickets,serverCount,totalCents,driverCents,kitchenCents,serversCents,serverShares:Array.from({length:serverCount},(_,i)=>each+(i<extra?1:0))};}
export function validSavedTips(tips){if(!tips||!Array.isArray(tips.tickets))return false;try{const actual=calculateTips(tips.tickets.map(x=>({ticket:x.ticket,amount:(x.cents/100).toFixed(2)})),tips.serverCount);return ['totalCents','driverCents','kitchenCents','serversCents'].every(k=>tips[k]===actual[k])&&JSON.stringify(tips.serverShares)===JSON.stringify(actual.serverShares);}catch{return false;}}

export const newTipCalculator=(amount='0')=>({display:amount,acc:null,operator:null,fresh:true,trail:''});
export function tipCalculatorKey(state,key){const s={...state};if(key==='AC')return newTipCalculator();if(key==='back'){if(s.fresh)return {...s,display:'0',fresh:false};s.display=s.display.slice(0,-1)||'0';if(s.display==='-')s.display='0';return s;}if(/^[0-9.]$/.test(key)){if(s.fresh){s.display=key==='.'?'0.':key;s.fresh=false;if(!s.operator)s.trail='';}else if(key==='.'&&!s.display.includes('.'))s.display+='.';else if(key!=='.'){const fractional=s.display.split('.')[1];if(fractional?.length>=2)return s;if(s.display.replace(/\D/g,'').length>=9)return s;s.display=s.display==='0'?key:s.display+key;}return s;}
 if(!['+','−','×','÷','='].includes(key))return s;
 const cents=Math.round(Number(s.display)*100);if(!Number.isSafeInteger(cents))throw Error('Enter a valid amount.');
 if(s.operator&&!s.fresh){let value;if(s.operator==='+')value=s.acc+cents;if(s.operator==='−')value=s.acc-cents;if(s.operator==='×')value=Math.round(s.acc*cents/100);if(s.operator==='÷'){if(!cents)throw Error('Cannot divide by zero.');value=Math.round(s.acc*100/cents);}if(!Number.isSafeInteger(value)||Math.abs(value)>100000000)throw Error('Amount is too large.');s.display=(value/100).toFixed(2);s.trail+=`${(cents/100).toFixed(2)} `;s.acc=value;}
 else if(!s.operator){s.acc=cents;s.trail=`${(cents/100).toFixed(2)} `;}
 if(key==='='){s.operator=null;s.acc=null;s.fresh=true;s.trail=s.trail.trim();return s;}
 if(s.operator&&s.fresh)s.trail=s.trail.replace(/[+−×÷]\s*$/,'');s.operator=key;s.trail+=key+' ';s.fresh=true;return s;
}
